		Scan(&p.ID, &p.Amount, &p.Currency, &p.Status)
	if errors.Is(err, sql.ErrNoRows) {
		return p, ErrNotFound
	}
	if err != nil {
		return p, fmt.Errorf("load charge: %w", err)
	}
	return p, nil
}

